WITH filtered AS (SELECT id, order_id, unit_price, ROUND(quantity, 1) AS quantity_rounded, CASE WHEN quantity >= 7 THEN 'High' WHEN quantity >= 4 THEN 'Medium' ELSE 'Low' END AS quantity_tier FROM order_items WHERE product_id IS NOT NULL) SELECT * FROM (SELECT id, order_id, quantity_rounded, unit_price FROM filtered) src UNPIVOT (val FOR measure IN (quantity_rounded AS QUANTITY_ROUNDED, unit_price));
